modules.accordion:
.p-accordionpanel {
    display: flex;
    flex-direction: column;
    border-style: solid;
    border-width: dt('accordion.panel.border.width');
    border-color: dt('accordion.panel.border.color');
}

.p-accordionheader {
    all: unset;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: dt('accordion.header.padding');
    color: dt('accordion.header.color');
    background: dt('accordion.header.background');
    border-style: solid;
    border-width: dt('accordion.header.border.width');
    border-color: dt('accordion.header.border.color');
    font-weight: dt('accordion.header.font.weight');
    border-radius: dt('accordion.header.border.radius');
    transition:
        background dt('accordion.transition.duration'),
        color dt('accordion.transition.duration'),
        outline-color dt('accordion.transition.duration'),
        box-shadow dt('accordion.transition.duration');
    outline-color: transparent;
}

.p-accordionpanel:first-child > .p-accordionheader {
    border-width: dt('accordion.header.first.border.width');
    border-start-start-radius: dt('accordion.header.first.top.border.radius');
    border-start-end-radius: dt('accordion.header.first.top.border.radius');
}

.p-accordionpanel:last-child > .p-accordionheader {
    border-end-start-radius: dt('accordion.header.last.bottom.border.radius');
    border-end-end-radius: dt('accordion.header.last.bottom.border.radius');
}

.p-accordionpanel:last-child.p-accordionpanel-active > .p-accordionheader {
    border-end-start-radius: dt('accordion.header.last.active.bottom.border.radius');
    border-end-end-radius: dt('accordion.header.last.active.bottom.border.radius');
}

.p-accordionheader-toggle-icon {
    color: dt('accordion.header.toggle.icon.color');
}

.p-accordionpanel:not(.p-disabled) .p-accordionheader:focus-visible {
    box-shadow: dt('accordion.header.focus.ring.shadow');
    outline: dt('accordion.header.focus.ring.width') dt('accordion.header.focus.ring.style') dt('accordion.header.focus.ring.color');
    outline-offset: dt('accordion.header.focus.ring.offset');
}

.p-accordionpanel:not(.p-accordionpanel-active):not(.p-disabled) > .p-accordionheader:hover {
    background: dt('accordion.header.hover.background');
    color: dt('accordion.header.hover.color');
}

.p-accordionpanel:not(.p-accordionpanel-active):not(.p-disabled) .p-accordionheader:hover .p-accordionheader-toggle-icon {
    color: dt('accordion.header.toggle.icon.hover.color');
}

.p-accordionpanel:not(.p-disabled).p-accordionpanel-active > .p-accordionheader {
    background: dt('accordion.header.active.background');
    color: dt('accordion.header.active.color');
}

.p-accordionpanel:not(.p-disabled).p-accordionpanel-active > .p-accordionheader .p-accordionheader-toggle-icon {
    color: dt('accordion.header.toggle.icon.active.color');
}

.p-accordionpanel:not(.p-disabled).p-accordionpanel-active > .p-accordionheader:hover {
    background: dt('accordion.header.active.hover.background');
    color: dt('accordion.header.active.hover.color');
}

.p-accordionpanel:not(.p-disabled).p-accordionpanel-active > .p-accordionheader:hover .p-accordionheader-toggle-icon {
    color: dt('accordion.header.toggle.icon.active.hover.color');
}

.p-accordioncontent {
    display: grid;
    grid-template-rows: 1fr;
}

.p-accordioncontent-wrapper {
    min-height: 0;
}

.p-accordioncontent-content {
    border-style: solid;
    border-width: dt('accordion.content.border.width');
    border-color: dt('accordion.content.border.color');
    background-color: dt('accordion.content.background');
    color: dt('accordion.content.color');
    padding: dt('accordion.content.padding');
}

modules.blockui:
.p-blockui {
    position: relative;
}

.p-blockui-mask {
    border-radius: dt('blockui.border.radius');
}

.p-blockui-mask.p-overlay-mask {
    position: absolute;
}

.p-blockui-mask-document.p-overlay-mask {
    position: fixed;
}

modules.card:
.p-card {
    background: dt('card.background');
    color: dt('card.color');
    box-shadow: dt('card.shadow');
    border-radius: dt('card.border.radius');
    display: flex;
    flex-direction: column;
}

.p-card-caption {
    display: flex;
    flex-direction: column;
    gap: dt('card.caption.gap');
}

.p-card-body {
    padding: dt('card.body.padding');
    display: flex;
    flex-direction: column;
    gap: dt('card.body.gap');
}

.p-card-title {
    font-size: dt('card.title.font.size');
    font-weight: dt('card.title.font.weight');
}

.p-card-subtitle {
    color: dt('card.subtitle.color');
}

modules.divider:
.p-divider-horizontal {
    display: flex;
    width: 100%;
    position: relative;
    align-items: center;
    margin: dt('divider.horizontal.margin');
    padding: dt('divider.horizontal.padding');
}

.p-divider-horizontal:before {
    position: absolute;
    display: block;
    inset-block-start: 50%;
    inset-inline-start: 0;
    width: 100%;
    content: '';
    border-block-start: 1px solid dt('divider.border.color');
}

.p-divider-horizontal .p-divider-content {
    padding: dt('divider.horizontal.content.padding');
}

.p-divider-vertical {
    min-height: 100%;
    display: flex;
    position: relative;
    justify-content: center;
    margin: dt('divider.vertical.margin');
    padding: dt('divider.vertical.padding');
}

.p-divider-vertical:before {
    position: absolute;
    display: block;
    inset-block-start: 0;
    inset-inline-start: 50%;
    height: 100%;
    content: '';
    border-inline-start: 1px solid dt('divider.border.color');
}

.p-divider.p-divider-vertical .p-divider-content {
    padding: dt('divider.vertical.content.padding');
}

.p-divider-content {
    z-index: 1;
    background: dt('divider.content.background');
    color: dt('divider.content.color');
}

.p-divider-solid.p-divider-horizontal:before {
    border-block-start-style: solid;
}

.p-divider-solid.p-divider-vertical:before {
    border-inline-start-style: solid;
}

.p-divider-dashed.p-divider-horizontal:before {
    border-block-start-style: dashed;
}

.p-divider-dashed.p-divider-vertical:before {
    border-inline-start-style: dashed;
}

.p-divider-dotted.p-divider-horizontal:before {
    border-block-start-style: dotted;
}

.p-divider-dotted.p-divider-vertical:before {
    border-inline-start-style: dotted;
}

.p-divider-left:dir(rtl),
.p-divider-right:dir(rtl) {
    flex-direction: row-reverse;
}

modules.fieldset:
.p-fieldset {
    background: dt('fieldset.background');
    border: 1px solid dt('fieldset.border.color');
    border-radius: dt('fieldset.border.radius');
    color: dt('fieldset.color');
    padding: dt('fieldset.padding');
    margin: 0;
}

.p-fieldset-legend {
    background: dt('fieldset.legend.background');
    border-radius: dt('fieldset.legend.border.radius');
    border-width: dt('fieldset.legend.border.width');
    border-style: solid;
    border-color: dt('fieldset.legend.border.color');
    color: dt('fieldset.legend.color');
    padding: dt('fieldset.legend.padding');
    transition:
        background dt('fieldset.transition.duration'),
        color dt('fieldset.transition.duration'),
        outline-color dt('fieldset.transition.duration'),
        box-shadow dt('fieldset.transition.duration');
}

.p-fieldset-toggleable > .p-fieldset-legend {
    padding: 0;
}

.p-fieldset-toggle-button {
    cursor: pointer;
    user-select: none;
    overflow: hidden;
    position: relative;
    text-decoration: none;
    display: flex;
    gap: dt('fieldset.legend.gap');
    align-items: center;
    justify-content: center;
    padding: dt('fieldset.legend.padding');
    background: transparent;
    border: 0 none;
    border-radius: dt('fieldset.legend.border.radius');
    transition:
        background dt('fieldset.transition.duration'),
        color dt('fieldset.transition.duration'),
        outline-color dt('fieldset.transition.duration'),
        box-shadow dt('fieldset.transition.duration');
    outline-color: transparent;
}

.p-fieldset-legend-label {
    font-weight: dt('fieldset.legend.font.weight');
}

.p-fieldset-toggle-button:focus-visible {
    box-shadow: dt('fieldset.legend.focus.ring.shadow');
    outline: dt('fieldset.legend.focus.ring.width') dt('fieldset.legend.focus.ring.style') dt('fieldset.legend.focus.ring.color');
    outline-offset: dt('fieldset.legend.focus.ring.offset');
}

.p-fieldset-toggleable > .p-fieldset-legend:hover {
    color: dt('fieldset.legend.hover.color');
    background: dt('fieldset.legend.hover.background');
}

.p-fieldset-toggle-icon {
    color: dt('fieldset.toggle.icon.color');
    transition: color dt('fieldset.transition.duration');
}

.p-fieldset-toggleable > .p-fieldset-legend:hover .p-fieldset-toggle-icon {
    color: dt('fieldset.toggle.icon.hover.color');
}

.p-fieldset-content-container {
    display: grid;
    grid-template-rows: 1fr;
}

.p-fieldset-content-wrapper {
    min-height: 0;
}

.p-fieldset-content {
    padding: dt('fieldset.content.padding');
}

modules.inplace:
.p-inplace-display {
    display: inline-block;
    cursor: pointer;
    border: 1px solid transparent;
    padding: dt('inplace.padding');
    border-radius: dt('inplace.border.radius');
    transition:
        background dt('inplace.transition.duration'),
        color dt('inplace.transition.duration'),
        outline-color dt('inplace.transition.duration'),
        box-shadow dt('inplace.transition.duration');
    outline-color: transparent;
}

.p-inplace-display:not(.p-disabled):hover {
    background: dt('inplace.display.hover.background');
    color: dt('inplace.display.hover.color');
}

.p-inplace-display:focus-visible {
    box-shadow: dt('inplace.focus.ring.shadow');
    outline: dt('inplace.focus.ring.width') dt('inplace.focus.ring.style') dt('inplace.focus.ring.color');
    outline-offset: dt('inplace.focus.ring.offset');
}

.p-inplace-content {
    display: block;
}

modules.panel:
.p-panel {
    display: block;
    border: 1px solid dt('panel.border.color');
    border-radius: dt('panel.border.radius');
    background: dt('panel.background');
    color: dt('panel.color');
}

.p-panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: dt('panel.header.padding');
    background: dt('panel.header.background');
    color: dt('panel.header.color');
    border-style: solid;
    border-width: dt('panel.header.border.width');
    border-color: dt('panel.header.border.color');
    border-radius: dt('panel.header.border.radius');
}

.p-panel-toggleable .p-panel-header {
    padding: dt('panel.toggleable.header.padding');
}

.p-panel-title {
    line-height: 1;
    font-weight: dt('panel.title.font.weight');
}

.p-panel-content-container {
    display: grid;
    grid-template-rows: 1fr;
}

.p-panel-content-wrapper {
    min-height: 0;
}

.p-panel-content {
    padding: dt('panel.content.padding');
}

.p-panel-footer {
    padding: dt('panel.footer.padding');
}

modules.scrollpanel:
.p-scrollpanel-content-container {
    overflow: hidden;
    width: 100%;
    height: 100%;
    position: relative;
    z-index: 1;
    float: left;
}

.p-scrollpanel-content {
    height: calc(100% + calc(2 * dt('scrollpanel.bar.size')));
    width: calc(100% + calc(2 * dt('scrollpanel.bar.size')));
    padding-inline: 0 calc(2 * dt('scrollpanel.bar.size'));
    padding-block: 0 calc(2 * dt('scrollpanel.bar.size'));
    position: relative;
    overflow: auto;
    box-sizing: border-box;
    scrollbar-width: none;
}

.p-scrollpanel-content::-webkit-scrollbar {
    display: none;
}

.p-scrollpanel-bar {
    position: relative;
    border-radius: dt('scrollpanel.bar.border.radius');
    z-index: 2;
    cursor: pointer;
    opacity: 0;
    outline-color: transparent;
    background: dt('scrollpanel.bar.background');
    border: 0 none;
    transition:
        outline-color dt('scrollpanel.transition.duration'),
        opacity dt('scrollpanel.transition.duration');
}

.p-scrollpanel-bar:focus-visible {
    box-shadow: dt('scrollpanel.bar.focus.ring.shadow');
    outline: dt('scrollpanel.barfocus.ring.width') dt('scrollpanel.bar.focus.ring.style') dt('scrollpanel.bar.focus.ring.color');
    outline-offset: dt('scrollpanel.barfocus.ring.offset');
}

.p-scrollpanel-bar-y {
    width: dt('scrollpanel.bar.size');
    inset-block-start: 0;
}

.p-scrollpanel-bar-x {
    height: dt('scrollpanel.bar.size');
    inset-block-end: 0;
}

.p-scrollpanel-hidden {
    visibility: hidden;
}

.p-scrollpanel:hover .p-scrollpanel-bar,
.p-scrollpanel:active .p-scrollpanel-bar {
    opacity: 1;
}

.p-scrollpanel-grabbed {
    user-select: none;
}

modules.splitter:
.p-splitter {
    display: flex;
    flex-wrap: nowrap;
    border: 1px solid dt('splitter.border.color');
    background: dt('splitter.background');
    border-radius: dt('border.radius.md');
    color: dt('splitter.color');
}

.p-splitter-vertical {
    flex-direction: column;
}

.p-splitter-gutter {
    flex-grow: 0;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1;
    background: dt('splitter.gutter.background');
}

.p-splitter-gutter-handle {
    border-radius: dt('splitter.handle.border.radius');
    background: dt('splitter.handle.background');
    transition:
        outline-color dt('splitter.transition.duration'),
        box-shadow dt('splitter.transition.duration');
    outline-color: transparent;
}

.p-splitter-gutter-handle:focus-visible {
    box-shadow: dt('splitter.handle.focus.ring.shadow');
    outline: dt('splitter.handle.focus.ring.width') dt('splitter.handle.focus.ring.style') dt('splitter.handle.focus.ring.color');
    outline-offset: dt('splitter.handle.focus.ring.offset');
}

.p-splitter-horizontal.p-splitter-resizing {
    cursor: col-resize;
    user-select: none;
}

.p-splitter-vertical.p-splitter-resizing {
    cursor: row-resize;
    user-select: none;
}

.p-splitter-horizontal > .p-splitter-gutter > .p-splitter-gutter-handle {
    height: dt('splitter.handle.size');
    width: 100%;
}

.p-splitter-vertical > .p-splitter-gutter > .p-splitter-gutter-handle {
    width: dt('splitter.handle.size');
    height: 100%;
}

.p-splitter-horizontal > .p-splitter-gutter {
    cursor: col-resize;
}

.p-splitter-vertical > .p-splitter-gutter {
    cursor: row-resize;
}

.p-splitterpanel {
    flex-grow: 1;
    overflow: hidden;
}

.p-splitterpanel-nested {
    display: flex;
}

.p-splitterpanel .p-splitter {
    flex-grow: 1;
    min-width: 0;
    min-height: 0;
    border: 0 none;
}

modules.toolbar:
.p-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    padding: dt('toolbar.padding');
    background: dt('toolbar.background');
    border: 1px solid dt('toolbar.border.color');
    color: dt('toolbar.color');
    border-radius: dt('toolbar.border.radius');
    gap: dt('toolbar.gap');
}

.p-toolbar-start,
.p-toolbar-center,
.p-toolbar-end {
    display: flex;
    align-items: center;
}

modules.base:
*,
::before,
::after {
    box-sizing: border-box;
}

.p-collapsible-enter-active {
    animation: p-animate-collapsible-expand 0.2s ease-out;
    overflow: hidden;
}

.p-collapsible-leave-active {
    animation: p-animate-collapsible-collapse 0.2s ease-out;
    overflow: hidden;
}

@keyframes p-animate-collapsible-expand {
    from {
        grid-template-rows: 0fr;
    }
    to {
        grid-template-rows: 1fr;
    }
}

@keyframes p-animate-collapsible-collapse {
    from {
        grid-template-rows: 1fr;
    }
    to {
        grid-template-rows: 0fr;
    }
}

.p-disabled,
.p-disabled * {
    cursor: default;
    pointer-events: none;
    user-select: none;
}

.p-disabled,
.p-component:disabled {
    opacity: dt('disabled.opacity');
}

.pi {
    font-size: dt('icon.size');
}

.p-icon {
    width: dt('icon.size');
    height: dt('icon.size');
}

.p-overlay-mask {
    background: var(--px-mask-background, dt('mask.background'));
    color: dt('mask.color');
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
}

.p-overlay-mask-enter-active {
    animation: p-animate-overlay-mask-enter dt('mask.transition.duration') forwards;
}

.p-overlay-mask-leave-active {
    animation: p-animate-overlay-mask-leave dt('mask.transition.duration') forwards;
}

@keyframes p-animate-overlay-mask-enter {
    from {
        background: transparent;
    }
    to {
        background: var(--px-mask-background, dt('mask.background'));
    }
}
@keyframes p-animate-overlay-mask-leave {
    from {
        background: var(--px-mask-background, dt('mask.background'));
    }
    to {
        background: transparent;
    }
}

.p-anchored-overlay-enter-active {
    animation: p-animate-anchored-overlay-enter 300ms cubic-bezier(.19,1,.22,1);
}

.p-anchored-overlay-leave-active {
    animation: p-animate-anchored-overlay-leave 300ms cubic-bezier(.19,1,.22,1);
}

@keyframes p-animate-anchored-overlay-enter {
    from {
        opacity: 0;
        transform: scale(0.93);
    }
}

@keyframes p-animate-anchored-overlay-leave {
    to {
        opacity: 0;
        transform: scale(0.93);
    }
}
